const raw = $input.first().json;
const body = raw.body || raw;

const userEmail = (body.user_email || '').trim();
const issue = (body.issue || '').trim();

const errors = [];
const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

if (!issue) {
  errors.push('issue must not be empty');
}

if (!userEmail || !emailRegex.test(userEmail)) {
  errors.push('user_email must be a valid email');
}

return [{
  json: {
    user_email: userEmail,
    issue,
    validation_status: errors.length === 0 ? 'valid' : 'invalid',
    validation_errors: errors
  }
}];

const item = $input.first().json;
const now = new Date();
const stamp = now.toISOString().replace(/[-:.TZ]/g, '').slice(0, 14);
const rand = Math.floor(Math.random() * 9000 + 1000);

return [{
  json: {
    ticket_id: `TICK-${stamp}-${rand}`,
    user_email: item.user_email,
    issue: item.issue,
    status: 'open',
    created_at: now.toISOString(),
    updated_at: now.toISOString()
  }
}];

const row = $input.first().json;
const rawOutput = row.output || row.text || '{}';

let parsed = {};
try {
  const match = rawOutput.match(/\{[\s\S]*?\}/);
  parsed = match ? JSON.parse(match[0]) : {};
} catch (e) {
  parsed = {};
}

return [{
  json: {
    ...row,
    ai_category: parsed.category || '',
    ai_priority: parsed.priority || '',
    ai_short_summary: parsed.short_summary || ''
  }
}];

const item = $input.first().json;
const txt = `${item.issue} ${item.ai_short_summary}`.toLowerCase();

let category = 'General';
const aiCategory = (item.ai_category || '').toLowerCase();
if (aiCategory.includes('bill') || /payment|refund|billing/.test(txt)) {
  category = 'Billing';
} else if (aiCategory.includes('tech') || aiCategory.includes('login') || /login|bug|error|system/.test(txt)) {
  category = 'Technical';
}

let priority = 'Medium';
const aiPriority = (item.ai_priority || '').toLowerCase();
if (aiPriority.includes('high') || /urgent|immediately|production down|blocked/.test(txt)) {
  priority = 'High';
}

const shortSummary = item.ai_short_summary || item.issue.slice(0, 140);

return [{
  json: {
    ...item,
    category,
    priority,
    short_summary: shortSummary,
    routed_queue: category === 'Technical' ? 'technical_queue' : 'general_queue',
    escalation_level: priority === 'High' ? 'urgent' : 'standard',
    updated_at: new Date().toISOString()
  }
}];
